  "steps": [
    {
      "title": "A Right-Angled Triangle",
      "say": "Let's start with a right triangle with legs a and b, and hypotenuse c.",
      "ops": [
        {"op": "write", "id": "title", "x": 60, "y": 40, "text": "Proof of the Pythagorean Theorem", "size": 52},
        {"op": "path", "id": "tri_base", "d": "M 200 400 L 440 400 L 200 220 Z", "color": "blue", "width": 4, "fill": "blue"},
        {"op": "path", "id": "right_angle", "d": "M 200 370 L 230 370 L 230 400", "color": "ink", "width": 3},
        {"op": "write", "id": "lbl_a", "x": 160, "y": 300, "text": "a", "size": 36, "color": "ink"},
        {"op": "write", "id": "lbl_b", "x": 310, "y": 415, "text": "b", "size": 36, "color": "ink"},
